#include <algorithm>
#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;
int main() {
    int t; cin >> t;
    while (t--) {
        int r; cin >> r;
        vector<int> houses(r);
        int sum = 0;
        for (int i = 0; i < r; i++) {
            cin >> houses[i];
            sum += houses[i];
        }
        int place = houses[r / 2];
        int answer = 0;
        for (int i = 0; i < r; i++) {
            answer += abs(houses[i] - place);
        }
        cout << answer << '\n';
    }
}
